public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null || arr.length == 0) {
        return;
    }
    // Clamp indices to array bounds
    int lower = Math.max(0, Math.min(from, arr.length - 1));
    int upper = Math.max(0, Math.min(to, arr.length - 1));
    if (lower >= upper) {
        return;
    }
    while (lower < upper) {
        V temp = arr[lower];
        arr[lower] = arr[upper];
        arr[upper] = temp;
        lower++;
        upper--;
    }
}

